# PTX source for mean reduction over dimension 1 (shape [B, D1, D2] -> [B, D2])
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry mean_reduce(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 dim1,
    .param .u32 dim2
)
{
    // ----- load parameters -----
    .reg .u64   %input, %output;
    .reg .u32   %batch, %dim1, %dim2;
    ld.param.u64 %input,  [input_ptr];
    ld.param.u64 %output, [output_ptr];
    ld.param.u32 %batch,  [batch];
    ld.param.u32 %dim1,   [dim1];
    ld.param.u32 %dim2,   [dim2];

    // ----- thread indexing -----
    .reg .u32   %tid_x, %ctaid_x, %ntid_x;
    .reg .u32   %global_tid, %total_out;
    mov.u32 %tid_x,    %tid.x;
    mov.u32 %ctaid_x,  %ctaid.x;
    mov.u32 %ntid_x,   %ntid.x;
    mad.lo.u32 %global_tid, %ctaid_x, %ntid_x, %tid_x;               // global thread id

    mul.lo.u32 %total_out, %batch, %dim2;                            // total output elements

    // if thread out of range, exit
    .reg .pred %p_exit;
    setp.ge.u32 %p_exit, %global_tid, %total_out;
    @%p_exit ret;

    // ----- compute (b,i) coordinates -----
    .reg .u32 %b, %i;
    div.u32 %b, %global_tid, %dim2;          // b = tid / dim2
    rem.u32 %i, %global_tid, %dim2;          // i = tid % dim2

    // pre‑compute some strides
    .reg .u32 %dim1_dim2;
    mul.lo.u32 %dim1_dim2, %dim1, %dim2;     // dim1 * dim2

    .reg .u32 %base;
    mad.lo.u32 %base, %b, %dim1_dim2, %i;    // base = b*dim1*dim2 + i

    // ----- reduction loop -----
    .reg .f32 %sum;
    mov.f32 %sum, 0f0;

    .reg .u32 %k, %idx;
    mov.u32 %k, 0;

LOOP:
    // idx = base + k*dim2
    mad.lo.u32 %idx, %k, %dim2, %base;

    // address = input + idx*2 (since FP16 = 2 bytes)
    .reg .u64 %addr_offset, %addr;
    cvt.u64.u32 %addr_offset, %idx;
    shl.b64 %addr_offset, %addr_offset, 1;
    add.u64 %addr, %input, %addr_offset;

    // load half, convert to float
    .reg .f16 %val_h;
    .reg .f32 %val_f;
    ld.global.f16 %val_h, [%addr];
    cvt.f32.f16 %val_f, %val_h;

    // accumulate
    add.f32 %sum, %sum, %val_f;

    // k++
    add.u32 %k, %k, 1;
    .reg .pred %p_loop;
    setp.lt.u32 %p_loop, %k, %dim1;
    @%p_loop bra LOOP;

    // ----- compute mean -----
    .reg .f32 %inv_dim1;
    cvt.f32.u32 %inv_dim1, %dim1;
    rcp.approx.f32 %inv_dim1, %inv_dim1;          // 1 / dim1
    mul.f32 %sum, %sum, %inv_dim1;

    // convert back to half
    .reg .f16 %out_h;
    cvt.rn.f16.f32 %out_h, %sum;

    // ----- store result -----
    // output index = b*dim2 + i
    .reg .u32 %out_idx;
    mad.lo.u32 %out_idx, %b, %dim2, %i;

    cvt.u64.u32 %addr_offset, %out_idx;
    shl.b64 %addr_offset, %addr_offset, 1;
    add.u64 %addr, %output, %addr_offset;

    st.global.f16 [%addr], %out_h;

    ret;
}
'''

